# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List, Sequence, Tuple
from rosterkit.models import Student

Cells = Tuple[str, str, str]

def _name_key(student: Student) -> Tuple[str, str]:
    name = student.display_name.casefold()
    return (name, student.student_id)

def _require_email(student: Student) -> str:
    if not (student.email or "").strip():
        name = student.display_name
        raise ValueError(f"no email: {name}")
    return student.email.strip()

def _cells(student: Student) -> Cells:
    mail = _require_email(student)
    return (student.display_name, student.section, mail)

def _join(entry: Cells, widths: Sequence[int]) -> str:
    parts = zip(entry, widths)
    cols = [word.ljust(wide) for word, wide in parts]
    return "  ".join(cols).rstrip()

def _widths(cells: Sequence[Cells]) -> List[int]:
    return [
        max(len(entry[slot]) for entry in cells)
        for slot in range(3)
    ]

# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Aligned name, section, email rows sorted by name."""
    roster = sorted(students, key=_name_key)
    if not roster:
        raise ValueError("no students to list")
    cells = [_cells(item) for item in roster]
    widths = _widths(cells)
    return [_join(entry, widths) for entry in cells]
